"""Run the Phase 6 DEVELOPMENT-ONLY deterministic evaluation and write reports/phase6_dev_report.md (every table is generated from evals/results/dev_eval.json).

    python scripts/run_dev_eval.py            # about 3-5 minutes; needs the generated dev data and the Phase 2/4 outputs; makes NO network or Gemini call

ALL DATA IS SYNTHETIC; experiments are SIMULATED; the ledger is a SANDBOX. Dev seed 1 only; the held-out status below is read from files.
"""
import json
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from evals import dev_eval as E  # noqa: E402


def df(rows, cols=None):
    d = pd.DataFrame(rows)
    return d[cols] if cols is not None and len(d) else d


def write_report(R: dict):
    pol, ab, fc = R["policy"], R["policy"]["abstention"], R["forecasting"]
    ov = pol["overall"]
    L = ["# Phase 6 development-only evaluation (generated by scripts/run_dev_eval.py)", "",
         "**DEVELOPMENT SEED 1 ONLY. ALL DATA IS SYNTHETIC; experiments are SIMULATED; the ledger is a SANDBOX.** These are development results on the seed the rules and configuration were "
         "developed on; they are not held-out evidence and make no claim about real players, a real ad network or any live model. The criteria (`evals/criteria.yaml`) were committed "
         "before the first run; no rule, threshold, seed or scenario expectation was changed to change a number below.", "",
         "## 0. What this report is not", "",
         f"- **Live Gemini verification: {R['live']['status']}** (blocked by a recorded billing state; the separate Groq live runs are summarised in the README, not here). Valid live Gemini agent runs: {R['live']['valid_live_agent_runs']}; recordings in `demo/`: {R['live']['recordings_in_demo'] or 'none'}. The failed live attempts are preserved (section 7) and are not agent evidence.",
         "- **No agent-vs-baseline comparison is made.** The rules-only policy is the baseline; the only agent results here are MOCK plumbing tests (section 6).",
         *held_out_lines(R),
         "## 1. Forecasting (the Phase 2 multiplier baseline), scored on matured outcomes only", "",
         f"Scored as of {fc['scoring_as_of']}. Interval coverage is compared with the nominal {fc['coverage_nominal']:.2f}; no pass/fail threshold was set and nominal calibration is not claimed: "
         f"overall coverage is {fc['table'][0]['coverage']:.3f} for cohorts and {fc['table'][1]['coverage']:.3f} for weekly summaries, i.e. UNDER nominal.", "",
         "`interval_width_over_forecast_mean` is the registered metric (mean of (hi - lo) / forecast among items that have an interval). The median is shown separately under its own name; "
         "an earlier version of this report showed the median under the registered name, which was an implementation error (corrected).", "",
         E.md(df(fc["table"]), 4), "",
         "Breakdown applicability (registered breakdowns: overall, by channel, by method, by period):", ""]
    for level, d in fc["breakdown_applicability"].items():
        L += [f"- **{level}**: " + "; ".join(f"{b}: {v}" for b, v in d.items())]
    chk = fc["independent_width_check"]
    L += ["", "Coverage and interval width are **not applicable** (shown blank) in groups where no item has an interval: " + (", ".join(fc["groups_without_any_interval_so_coverage_and_width_are_not_applicable"]) or "(none)") + ".", "",
          f"Independent cross-check of the interval width from the raw tables (plain pandas, not the scorer; {chk['n_with_interval']} cohort forecasts with an interval): mean {chk['mean_width_over_forecast']!r} "
              f"(scorer {chk['scorer_mean']!r}, match: {chk['mean_matches_scorer']}); median {chk['median_width_over_forecast']!r} (scorer {chk['scorer_median']!r}, match: {chk['median_matches_scorer']}); "
              f"mean differs from median: {chk['mean_differs_from_median']}.", "",
          f"Accounting: cohort forecasts {fc['cohort_accounting']}; weekly summaries {fc['summary_accounting']}.", "",
          "Cohorts withheld from forecasting, by reason (the exclusions; their revenue is not in the scores above):", "",
          E.md(df([{"reason": k, **{a: b for a, b in v.items() if a != "by_channel"}, "by_channel": v["by_channel"]} for k, v in fc["withheld_by_reason"].items()])), "",
          f"Reference forecast that ignores D3 information: {json.dumps(fc['reference_baseline_ignoring_d3'], default=str)[:400]}", ""]
    L += [
         "## 2. Policy decisions against the committed scenario expectations", "",
         f"The deterministic rules policy was run for all 14 dev reviews (static sandbox budgets, as in the Phase 3 report). {int(ov['n_scored'])} channel-reviews fall inside a scenario's evaluation window and are scored; "
         f"{pol['n_background']} of {pol['n_channel_reviews']} channel-reviews have no scenario expectation and are not scored.", "",
         "Overall: " + ", ".join(f"{k} = {ov[k]:.3f}" if isinstance(ov[k], float) else f"{k} = {ov[k]}" for k in ("n_scored", "ideal", "acceptable", "forbidden", "unlisted", "ideal_rate", "acceptable_or_better_rate", "forbidden_rate", "unlisted_rate")), "",
         "Pre-registered class definitions: ideal and acceptable come from each scenario's lists; a row is `forbidden` when its action is in the scenario's own `forbidden_actions` list, i.e. it **violates a committed scenario expectation**; "
         "`unlisted` is any other action. A `forbidden` row is NOT independent proof that the action would have caused economic harm: the expectations are design intents written before the data existed, and the policy's decrease rule is a documented heuristic. "
         "A rate is a count divided by n_scored.", "",
         E.md(df(pol["per_scenario"])), "",
         "### Violations of the committed scenario expectations (every forbidden or unlisted row, as found)", "",
         E.md(df(pol["forbidden_or_unlisted"], ["scenario", "channel", "date", "action", "class", "ideal", "acceptable", "forbidden", "reason"])), "",
         "These are reported, not fixed: the expectations were written before any data existed and are compared with commit c3447c8 by a test; no policy value was changed in response.", "",
         "### All scored rows", "", E.md(df(pol["rows"], ["scenario", "channel", "date", "action", "class", "ideal", "acceptable", "forbidden"])), "",
         "### Unscored background (no scenario expectation): action counts", "", E.md(df(pol["background_unscored_actions"])), "",
         "## 3. Abstentions (insufficient_evidence)", "",
         f"- abstention recall (rows where insufficient_evidence is the only ideal action: {ab['n_rows_where_ie_is_the_only_ideal']}): {ab['recall']}",
         f"- abstentions on scored rows: {ab['n_abstained']}; appropriateness (ideal or acceptable): {ab['appropriateness']}",
         "", "False abstentions (policy abstained, abstention neither ideal nor acceptable):", "", E.md(df(ab["false_abstentions"], ["scenario", "channel", "date", "action", "ideal", "acceptable", "forbidden", "reason"])), "",
         "Missed abstentions (abstention was ideal or acceptable under the scenario, but the policy took an action the scenario lists as forbidden; again a violation of the committed expectation, not proven harm):", "", E.md(df(ab["missed_abstentions"], ["scenario", "channel", "date", "action", "ideal", "acceptable", "forbidden", "reason"])), "",
         "Why the policy held or abstained, over ALL channel-reviews (first stated reason, numbers masked):", "", E.md(df(pol["reasons_table"])), "",
         "## 4. Constraints: adversarial suite run through the real code paths", "",
         "Each case is expected to be REFUSED with the stated code. Layers: `constraints` = `check_constraints`; `ledger` = the sandbox ledger; `agent_validator` = the Phase 5 validator on a SYNTHETIC fixture review (hand-made, as in the unit tests).", "",
         E.md(df(R["constraints"], ["id", "case", "layer", "expected", "observed", "refused_as_expected"])), "",
         f"Result: {sum(c['refused_as_expected'] for c in R['constraints'])} of {len(R['constraints'])} cases refused as expected."
         + ("" if all(c["refused_as_expected"] for c in R["constraints"]) else " **DEFECT: at least one case was not refused as expected (see the table).**"), "",
         "## 5. Experiment safeguards (SIMULATED experiments)", "",
         "(a) The regression safeguards, executed now as named pytest groups (criteria.yaml):", "",
         E.md(df(R["experiment_safeguards"]["groups"])), "",
         f"pytest return code {R['experiment_safeguards']['pytest_returncode']}; wall time {R['experiment_safeguards']['wall_seconds']} s. Per-test outcomes are in `evals/results/dev_eval.json`.", "",
         f"(b) Planning-study statistics as found in `reports/phase4_results.json`. The ONLY experiment-design study that exists is for the **{R['experiment_safeguards']['study_statistics']['channel_studied']}** channel at the "
         f"{R['experiment_safeguards']['study_statistics']['review_date_studied']} review: its test is INADEQUATE at every declared scale in the dev-seed world. The demonstration world is a separately declared synthetic world, not that channel. "
         f"**Adequacy for every other channel, including meta (the steady_winner scenario's channel), is UNKNOWN: no study of it exists, and nothing here should be read as saying it is adequate or inadequate.**", "",
         "Dev-seed world, scale search:", "", E.md(df(R["experiment_safeguards"]["study_statistics"]["dev_world_scale_search"], ["scale", "adequate", "chosen_treatment_days", "power at 1.5x (56d)", "false-keep at 1.0x (56d)", "median SE of iROAS (56d, at 1.5x)"])), "",
         "Demonstration world, scale search:", "", E.md(df(R["experiment_safeguards"]["study_statistics"]["demonstration_world_scale_search"], ["scale", "adequate", "chosen_treatment_days", "power at 1.5x (56d)", "false-keep at 1.0x (56d)", "median SE of iROAS (56d, at 1.5x)"])), "",
         "Evaluation-side replicate studies (the actual simulator re-run through the same estimator and rule) and the one readout scored against the simulator's truth:", "",
         E.md(df([{"design": "chosen (demonstration world)", **R["experiment_safeguards"]["study_statistics"]["replicate_study_chosen_design"]}, {"design": "dev-seed channel, scale 1 (inadequate)", **R["experiment_safeguards"]["study_statistics"]["replicate_study_scale1_design"]}])), "",
         f"Readout vs truth: {R['experiment_safeguards']['study_statistics']['readout_vs_truth']}", "",
         "## 6. Mock agent plumbing (NOT agent performance)", "",
         f"**{R['agent_plumbing_mock']['label']}** The scripted analyst follows the deterministic policy by construction, so action correctness is not reported. This checks that the real tools, validator and fallback work on all 14 real dev reviews.", "",
         E.md(df(R["agent_plumbing_mock"]["rows"])), "",
         f"Investigation coverage of the scenarios' `required_investigations` by the SCRIPTED analyst (mapping fixed in criteria.yaml; overall {R['agent_plumbing_mock']['coverage_overall']:.3f}). A gap describes the scripted analyst's economy, not any model; it shows how the metric will be computed for the live agent:", "",
         E.md(df(R["agent_plumbing_mock"]["coverage_by_scenario"])), "",
         "## 7. Live Gemini verification: " + R["live"]["status"], "",
         "Attempts, preserved as found (none is agent evidence):", ""]
    for a in R["live"]["attempts"]:
        runs = "; ".join(f"{r['as_of']} {r['status']}" + (f" ({r['fallback_reason']})" if r.get("fallback_reason") else "") for r in a.get("live_agent_runs", [])) or "no agent case ran"
        L.append(f"- attempt {a.get('attempt')}: verified model {a.get('verified_model')}; connectivity {a.get('connectivity_check')}; {runs}" + (f"; stopped: {a['selection_stopped'][:120]}" if a.get("selection_stopped") else ""))
    tb = R["tool_budget_amendment"]
    L += ["", "### Tool-budget amendment (kept visible)", "",
          f"`max_tool_calls` in force: **{tb['max_tool_calls_in_force']}** (max_model_turns {tb['max_model_turns']}, repair attempts {tb['repair_retries']}). Recorded in `config/agent.yaml`: \"{tb['recorded_note']}\"", "",
          "Later offline corrections (the budget is stated in the task prompt; calls past it are denied and the model gets one wrap-up turn to answer from what it holds) were tested ONLY with a scripted mock model. "
          "**Nothing shows yet that the live investigation problem is resolved for Gemini: that needs a valid live Gemini run, and none exists (the separate Groq evidence is summarised in the README).** The amendment was made after seeing live attempt 2, not to obtain a particular outcome.", "",
          "### Criteria amendments (appended to `evals/criteria.yaml`; the registered definitions themselves are unchanged)", ""]
    L += [f"- {a['date']} ({a['kind']}): {' '.join(str(a['what']).split())}" for a in R["criteria_amendments"]] or ["- (none)"]
    L += ["", "## 8. Development snapshot of what a future freeze must cover (NOT a freeze)", "",
          E.md(pd.DataFrame([{"item": k, "sha256": v} for k, v in R["dev_manifest"]["hashes"].items()])), "",
          "## 9. Reading this report", "",
          "- Every table above was generated by `scripts/run_dev_eval.py` from an actual run; elapsed " + f"{R['elapsed_seconds']} s.",
          "- Scenario disagreements and any DEFECT are findings for review. They were not fixed here.",
          "- These results describe the deterministic rules baseline and the safeguards on the development seed. Whether a live agent helps is not measured here."]
    (ROOT / "reports" / "phase6_dev_report.md").write_text("\n".join(L), encoding="utf-8")


def held_out_lines(R) -> list:
    """State-aware: this dev report is regenerated before AND after the held-out baseline run, so it must not claim the seeds are untouched once they are not."""
    lock = ROOT / "evals" / "results" / "heldout" / "RUN_LOCK.json"
    if not lock.exists():
        return [f"- **Held-out seeds {R['held_out']['heldout_seeds']} are untouched** (data present: {R['held_out']['data_present_for_heldout_seeds'] or 'none'}; the generator refuses them without the explicit flag: {R['held_out']['generator_refuses_without_allow_flag']}). "
                "No freeze has happened; the hashes in section 8 are a development snapshot.",
                "- **The evaluation is incomplete**: the live agent evaluation and the held-out run have not been done.", ""]
    fid = json.loads(lock.read_text(encoding="utf-8"))["freeze_id"]
    return [f"- **Held-out seeds {R['held_out']['heldout_seeds']} were used ONCE for the frozen deterministic rules-only baseline** (freeze `{fid}`; see `reports/heldout_baseline_report.md`). That run validates only the baseline; "
            "this report remains the development snapshot, and the hashes in section 8 are from before the freeze. Those seeds can no longer be described as untouched holdouts for an agent.",
            "- **The agent evaluation is not done**: Gemini live verification is pending, the single validated Groq proposal (see the README) is one case equal to the baseline, and no agent has been scored on any held-out seed.", ""]


def main():
    R = E.main()
    write_report(R)
    print("wrote reports/phase6_dev_report.md and evals/results/dev_eval.json")


if __name__ == "__main__":
    main()
